{
  "reviews": {
    "node-2wlj8x": {
      "supported": false,
      "issue": "The node claims AL-44 is active below 4.5 bar and clears above 5.0 bar based on source da0260c0..., but the evidence packet contains no measurement record showing these thresholds were met at the time of the incident (10:00 AM). The point register defines logic, not real-time state.",
      "evidenceNeeded": "A pressure sample or alarm log from IA-P01 or a similar source that explicitly records P-R pressure values around 4.5–5.0 bar at approximately 10:00 on May 20.","question":"Does any available evidence record the actual pressure value at point P-R between 9:58 and 10:03 AM?"
    },
    "node-w73rj6": {
      "supported": false,
      "issue": "The node asserts that AL-44 maps to receiving-header pressure rather than a compressor trip contact. While the point register excerpt states this mapping exists in PR-12, no evidence confirms whether the legacy 'COMP FAULT' label was still active at 10:00 AM or if any recent change had altered it.",
      "evidenceNeeded": "A screenshot of the operator screen from IA-S01 showing AL-44 text and mapping status at ~10:00, or a configuration log confirming PR-12 was in effect then.","question":"What did the alarm display for AL-44 exactly when it triggered?"
    },
    "node-npmygu": {
      "supported": false,
      "issue": "The node defines work scope as planned maintenance of 1SC dryer group D-101 with RHOB receiving operation. The cover (IA-S02) confirms this but does not specify which valves or isolation points were intended to be secured before air loss; the claim that 'receiving operation' was under preparation is vague and unsupported by a specific boundary definition.",
      "evidenceNeeded": "The work-boundary document ECP-1SC-04 (Rev 3) showing exactly which equipment, valves, or service lines were to be isolated for WO-527.","question":"Which specific isolation points did the crew intend to secure before starting maintenance?"
    }
  },
  "decision": {
    "summary": "All three proposed nodes are currently unsupported because they rely on either a single definition (point register) without real-time state evidence, or an assertion about scope that lacks explicit boundary details. The investigation must obtain actual pressure readings and the specific isolation plan before any causal chain can be validated.",
    "evidenceUsed": ["incident-description", "da0260c0-7d49-43e8-b074-da2a14c7d59c#1", "eaee59fe-70f4-4876-a21d-780814412078#1"],
    "unknowns": ["Actual P-R pressure at 10:00 AM","Whether AL-44 label was updated or still legacy","Exact isolation points intended for WO-527"],
    "alternatives": [
      "The air loss originated upstream (source) and propagated downstream, which would explain a header-wide drop without local valve action.",
      "A distribution valve failed open/closed contrary to procedure, but no record confirms this state."
    ],
    "confidence": 0.65
  }
}
